// Normaliza el payload de Wazuh y calcula la huella de deduplicación.
// Función SHA-256 pura en JavaScript sin dependencias de módulos externos (sandbox n8n).
function sha256(ascii) {
  function r(v, a) { return (v >>> a) | (v << (32 - a)); }
  const m = Math.pow, mw = m(2, 32);
  let i, j, res = '', w = [], abl = ascii.length * 8, h = [], k = [], pc = 0, ic = {};
  for (let c = 2; pc < 64; c++) {
    if (!ic[c]) {
      for (i = c * 2; i < 313; i += c) ic[i] = true;
      if (pc < 8) h[pc] = (m(c, 0.5) * mw) | 0;
      k[pc++] = (m(c, 1 / 3) * mw) | 0;
    }
  }
  ascii += '\x80';
  while ((ascii.length % 64) - 56) ascii += '\x00';
  for (i = 0; i < ascii.length; i++) {
    j = ascii.charCodeAt(i);
    w[i >> 2] |= j << (((3 - i) % 4) * 8);
  }
  w[w.length] = (abl / mw) | 0;
  w[w.length] = abl;
  for (j = 0; j < w.length;) {
    const W = w.slice(j, j += 16), oh = h;
    h = h.slice(0, 8);
    for (i = 0; i < 64; i++) {
      const w15 = W[i - 15], w2 = W[i - 2];
      const s0 = r(w15, 7) ^ r(w15, 18) ^ (w15 >>> 3);
      const s1 = r(w2, 17) ^ r(w2, 19) ^ (w2 >>> 10);
      const ch = (h[4] & h[5]) ^ (~h[4] & h[6]);
      const maj = (h[0] & h[1]) ^ (h[0] & h[2]) ^ (h[1] & h[2]);
      const t1 = h[7] + (r(h[4], 6) ^ r(h[4], 11) ^ r(h[4], 25)) + ch + k[i] + (W[i] = (i < 16) ? W[i] : (W[i - 16] + s0 + W[i - 7] + s1) | 0);
      const t2 = (r(h[0], 2) ^ r(h[0], 13) ^ r(h[0], 22)) + maj;
      h = [(t1 + t2) | 0].concat(h);
      h[4] = (h[4] + t1) | 0;
    }
    for (i = 0; i < 8; i++) h[i] = (h[i] + oh[i]) | 0;
  }
  for (i = 0; i < 8; i++) {
    for (j = 3; j >= 0; j--) {
      const b = (h[i] >> (j * 8)) & 255;
      res += (b < 16 ? '0' : '') + b.toString(16);
    }
  }
  return res;
}

return $input.all().map((item) => {
  const body = item.json.body ?? item.json;
  const alert = body.alert ?? body;
  const rule = alert.rule ?? {};
  const data = alert.data ?? {};
  const agent = alert.agent ?? {};

  const level = Number(rule.level ?? body.rule_level ?? 0);
  const severity = level >= 12 ? 'critical'
    : level >= 10 ? 'high'
    : level >= 7  ? 'medium'
    : level >= 4  ? 'low'
    : 'info';

  const source = (body.source ?? 'wazuh').toLowerCase();
  const title = String(rule.description ?? body.title ?? 'Alerta sin descripción').slice(0, 240);
  const srcIp = data.srcip ?? body.src_ip ?? null;
  const dstIp = data.dstip ?? body.dst_ip ?? null;
  const fpData = [source, rule.id ?? '', srcIp ?? '', dstIp ?? '', title.slice(0, 120)].join('|');
  const fingerprint = sha256(fpData);

  return {
    json: {
      external_id: String(alert.id ?? body.id ?? fingerprint.slice(0, 16)),
      source,
      rule_id: String(rule.id ?? body.rule_id ?? 'N/D'),
      rule_level: level,
      severity,
      title,
      description: alert.full_log ?? rule.description ?? body.description ?? '',
      src_ip: srcIp,
      dst_ip: dstIp,
      src_port: data.srcport ? Number(data.srcport) : null,
      dst_port: data.dstport ? Number(data.dstport) : null,
      protocol: data.protocol ?? null,
      username: data.dstuser ?? data.srcuser ?? null,
      agent_name: agent.name ?? body.agent_name ?? null,
      mitre_tactic: (rule.mitre?.tactic ?? []).join(', ') || null,
      mitre_technique: (rule.mitre?.id ?? []).join(', ') || null,
      fingerprint,
      detected_at: alert.timestamp ?? new Date().toISOString(),
      raw_payload: body
    }
  };
});

